$titulo_pagina='Meus Serviços'; $estilos_pagina=['/assets/css/admin.css?v=5']; require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/functions.php'; verificarProfissional(); $perfil=pegar_perfil_profissional_por_usuario($_SESSION['usuario_id']);
