input type="hidden" name="id" value="<?php echo (int)$oferta['id']; ?>"><button class="btn-small" type="submit"><?php echo $oferta['ativo']?'Pausar':'Publicar'; ?></button></form><form method="POST" onsubmit="return confirm('Remover este serviço?')"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?php echo (int)$oferta['id']; ?>"><button class="btn-small btn-danger" type="submit">Excluir</button></form></div></article><?php endforeach; ?></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
